function histogram(data, bins){
  bins = bins||32;
  var r=new Array(bins).fill(0), g=new Array(bins).fill(0), b=new Array(bins).fill(0), L=new Array(bins).fill(0);
  var n=data.length/4;
  for(var i=0;i<data.length;i+=4){
    var R=data[i],G=data[i+1],B=data[i+2];
    r[Math.min(bins-1,Math.floor(R*bins/256))]+=1;
    g[Math.min(bins-1,Math.floor(G*bins/256))]+=1;
    b[Math.min(bins-1,Math.floor(B*bins/256))]+=1;
    var lum=Math.round(0.299*R+0.587*G+0.114*B);
    L[Math.min(bins-1,Math.floor(lum*bins/256))]+=1;
  }
  function mx(a){var m=0;for(var k=0;k<a.length;k++)if(a[k]>m)m=a[k];return m;}
  return {r:r,g:g,b:b,lum:L,max:Math.max(mx(r),mx(g),mx(b),mx(L)),pixels:n};
}
var EXPORTS={ histogram:histogram };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HistogramForgePure = EXPORTS; }
